const cheerio = require('cheerio');
const results = [];
const seen = new Set();

const html = $input.first().json.data || '';
if (!html) return [{ json: { url: null, type: 'no_html' } }];

const $ = cheerio.load(html);

// Selector ladder — tries most specific first, falls back to broadest
const selectors = [
  'div[data-testid="list-view"] a[href*="/ip/"]',           // original
  'div[data-testid="search-result-listview-container"] a[href*="/ip/"]',
  'div[data-testid="item-stack"] a[href*="/ip/"]',
  '[data-testid="list-view-item"] a[href*="/ip/"]',
  'section[data-automation-id="product-list"] a[href*="/ip/"]',
  'a[href*="/ip/"][href*="walmart.com"]',                   // broader match
  'a[href*="/ip/"]'                                         // broadest fallback
];

let matched = false;
for (const sel of selectors) {
  $(sel).each((i, el) => {
    const url = $(el).attr('href');
    if (url) {
      const fullUrl = url.startsWith('http')
        ? url
        : `https://www.walmart.com${url}`;
      // Exclude non-product links that contain /ip/ in unrelated paths
      if (fullUrl.includes('walmart.com/ip/') && !seen.has(fullUrl)) {
        seen.add(fullUrl);
        results.push({ url: fullUrl, matchedSelector: sel });
      }
    }
  });
  if (results.length > 0) {
    matched = true;
    break; // stop at first selector that finds products
  }
}

const limited = results.slice(0, 5); // reduced to 5 to conserve credits

if (limited.length === 0) {
  return [{ json: { url: null, type: 'no_products_found', matchedSelector: 'none' } }];
}

return limited.map(r => ({ json: r }));

